@@ -5328,1 +5328,6 @@
-  zext(dst, dst, 32);
+  // li32 uses addiw which sign-extends; only need zext when bit 31 is set.
+  // Safe: narrow klass immediates are never patched at runtime on RISC-V
+  // (see metadata_Relocation::pd_fix_value).
+  if ((int32_t)nk < 0) {
+    zext(dst, dst, 32);
+  }
